import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.CoUqiBXn.js";import{An as i,Mn as a,jn as o,kn as s}from"./chunks/assets.D9KQ0sN9.js";var c=JSON.parse(`{"title":"Customize Pushed Findings","description":"","frontmatter":{},"headers":[],"relativePath":"cli/tools/customize-pushed-findings.md","filePath":"cli/tools/customize-pushed-findings.md","lastUpdated":0}`),l={name:`cli/tools/customize-pushed-findings.md`};function u(t,c,l,u,d,f){return r(),n(`div`,null,[...c[0]||=[e(`<h1 id="customize-pushed-findings" tabindex="-1">Customize Pushed Findings <a class="header-anchor" href="#customize-pushed-findings" aria-label="Permalink to “Customize Pushed Findings”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Deprecated</p><p>CLI importers are deprecated. Import scan results from the SysReptor web UI using the <a href="https://github.com/Syslifters/sysreptor/tree/main/plugins/scanimport" target="_blank" rel="noreferrer">scanimport</a> plugin instead.</p></div><p>When using <code>reptor &lt;plugin&gt; --push-findings</code>, reptor aggregates all findings by scan plugin (so that, e.g., &quot;SQL Injection&quot; is only added once for multiple affected systems). It uses descriptions from the scanning tools.</p><p>But sometimes, you want to customize the finding descriptions or ratings. Here&#39;s how you do it.</p><p><em>This description might not apply to all reptor tool plugins. It is, however, applicable at least to Nessus, OpenVAS, and Burp.</em></p><p>Let&#39;s say we want to replace the title and the CVSS score of the SQL injection finding in a Burp report.</p><h2 id="copy-default-templates-to-your-home-directory" tabindex="-1">Copy default templates to your home directory <a class="header-anchor" href="#copy-default-templates-to-your-home-directory" aria-label="Permalink to “Copy default templates to your home directory”">​</a></h2><p>The first step is to copy the templates shipped with reptor to your home directory. Use the following command:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reptor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugins</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --copy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> burp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This command copies the templates (usually in TOML format) to ~/.sysreptor/plugins/Burp/findings. Templates in this location override the default templates shipped with reptor. Changes in those templates are effective immediately.</p><h2 id="customize-templates-with-static-text" tabindex="-1">Customize templates with static text <a class="header-anchor" href="#customize-templates-with-static-text" aria-label="Permalink to “Customize templates with static text”">​</a></h2><p>The <code>global.toml</code> template holds the information populated to SysReptor when pushing findings.</p><p><img src="`+a+`" alt="Contents of global.toml" loading="lazy"></p><p>The variables use the Django template language but with <a href="/cli/writing-plugins/tools#formatting-tool-output">different markers</a> (enclosed in HTML comments). Changes in this file will affect all findings pushed from the command line to your SysReptor report.</p><p>If we want to customize the Burp SQL injection finding, we first need to find out the plugin ID (Burp calls it &quot;type&quot;) of the plugin. We find the ID 1049088 in the <a href="https://portswigger.net/kb/issues/00100200_sql-injection" target="_blank" rel="noreferrer">Portswigger Knowledge Base</a> or in the notes if we upload Burp findings as notes (using <code>reptor burp -i burp.xml --upload</code>).</p><p>We now copy <code>global.toml</code> and name it <code>1049088.toml</code>. We can now change the title and the CVSS score to static values:</p><p><img src="`+o+`" alt="Customized template" loading="lazy"></p><p>If we now push the finding (e.g., using <code>reptor burp -i burp.xml --push-findings --include 1049088</code>), reptor uses our custom title.</p><h2 id="customize-templates-with-dynamic-text" tabindex="-1">Customize templates with dynamic text <a class="header-anchor" href="#customize-templates-with-dynamic-text" aria-label="Permalink to “Customize templates with dynamic text”">​</a></h2><p>Burp includes lots of information in its reports that we do not use when pushing findings. You can check what variables exist using <code>reptor burp -i burp.xml --template-vars</code>.</p><p>You&#39;ll find, for example, the variable &quot;confidence&quot;:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;user-select:none;-webkit-user-select:none;">$ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">reptor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> burp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> burp.xml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template-vars</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">snip</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;severity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;high&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;confidence&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Firm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">snip</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>You can easily use this variable in your templates:</p><p><img src="`+i+`" alt="Customized template with &quot;confidence&quot;" loading="lazy"></p><h2 id="populate-your-changes-to-your-colleagues" tabindex="-1">Populate your changes to your colleagues <a class="header-anchor" href="#populate-your-changes-to-your-colleagues" aria-label="Permalink to “Populate your changes to your colleagues”">​</a></h2><p>Wouldn&#39;t it be nice if your colleagues could reuse your changes? That&#39;s easy.</p><p>Push your findings to your finding templates using <code>reptor burp --upload-finding-templates</code> (your user needs permission to edit finding templates).</p><p><img src="`+s+`" alt="Pushed Burp SQLi template" loading="lazy"></p><p>Finding templates having the tag &quot;&lt;plugin_name&gt;:&lt;plugin_id&gt;&quot; override local templates (shipped with reptor or in your home directory). The template is now effective for all SysReptor users using <code>reptor</code> to push Burp reports.</p>`,29)]])}var d=t(l,[[`render`,u]]);export{c as __pageData,d as default};